<script setup>
import { computed, ref, watch } from 'vue'
import { Activity, AlertTriangle, Check, ChevronRight, CircleHelp, FileCode2, Search, Sparkles } from 'lucide-vue-next'

const emit = defineEmits(['help'])

const scopes = [
  { id: 'all', label: '全部', count: 9 }, { id: 'global', label: '全局', count: 3 },
  { id: 'project', label: '项目', count: 2 }, { id: 'workspace', label: '空间', count: 3 }, { id: 'agent', label: 'Agent', count: 1 },
]
const skills = [
  { id: 'brainstorming', name: '发散收敛', version: '2.1.0', scope: 'global', scopeLabel: '全局', source: '官方', state: '可用', tokens: '1,240', description: '需求含糊、方案未定时先发散再收敛。不用于已有明确规格的实现任务。' },
  { id: 'pdf-extract', name: 'PDF 抽取', version: '1.4.2', scope: 'project', scopeLabel: '项目', source: '官方', state: '可用', tokens: '2,180', description: '从 PDF 中提取正文、表格和页面元数据，保留页码来源。' },
  { id: 'commit-helper', name: '提交规范', version: '1.2.0', scope: 'global', scopeLabel: '全局', source: '官方', state: '可用', tokens: '860', description: '根据仓库约定检查提交范围、消息格式和变更说明。' },
  { id: 'tdoc-orchestrator', name: '文档编排', version: '3.0.1', scope: 'workspace', scopeLabel: '工作空间', source: '官方', state: '可用', tokens: '1,560', description: '按文档任务编排资料收集、撰写、校验和交付步骤。' },
  { id: 'sheet-agent', name: '表格代理', version: '2.4.0', scope: 'workspace', scopeLabel: '工作空间', source: '官方', state: '可用', tokens: '1,920', description: '读取表格结构，处理公式、格式和数据核对。' },
  { id: 'k8s-deploy', name: '集群发布', version: '0.9.3', scope: 'project', scopeLabel: '项目', source: '社区', state: '缺依赖', tokens: '740', description: '生成并检查集群发布计划；执行前确认环境与依赖。' },
  { id: 'legacy-migrate', name: '旧系统迁移', version: '0.2.0', scope: 'agent', scopeLabel: 'Agent', source: '本地', state: '损坏', tokens: '—', description: '旧版迁移技能，入口文件校验失败，暂不可加载。' },
  { id: 'contract-review', name: '合同审阅', version: '1.0.4', scope: 'workspace', scopeLabel: '工作空间', source: '社区', state: '待复核', tokens: '510', description: '标记合同条款中的责任、期限和风险点，供人工复核。' },
  { id: 'ocr-image', name: '图片识别', version: '1.1.0', scope: 'global', scopeLabel: '全局', source: '官方', state: '可用', tokens: '290', description: '识别图片中的文字与基础版面信息。' },
]
const topics = [
  '包结构', '发现选择', '加载注入', '执行模型', '版本演进', '自进化', '绑定作用域', '依赖运行时', '安全', '生命周期', '创作支持', '市场生态', '可观测', '边界', '成熟度',
]
const topicDetails = [
  { title: '包结构规范', summary: 'SKILL.md 前置元数据（manifest）', note: '三段式描述：能做什么 / 什么时候用 / 什么时候不用。第三段最常被省略，也最能减少误选。' },
  { title: '发现与选择', summary: '按描述召回，再结合作用域和状态筛选候选 Skill', note: '先用短描述完成候选检索；只有命中后才读取正文，避免把整套技能塞进上下文。' },
  { title: '加载与注入', summary: '渐进式披露：元数据先行，正文按需加载', note: '记录每次注入的版本和 token 数，让上下文占用可解释、可追踪。' },
  { title: '执行模型', summary: '提示词指令与受控脚本分开声明', note: '脚本能力需要显式依赖、权限边界和可审计的输入输出。' },
  { title: '版本演进', summary: '语义化版本与兼容性检查', note: '发布新版本时保留旧版本快照，运行记录固定到实际使用的版本。' },
  { title: '自进化', summary: '反馈进入候选改进，不直接覆盖已发布版本', note: '由运行反馈生成草稿，经校验与复核后再发布。' },
  { title: '绑定作用域', summary: '全局、项目、工作空间和 Agent 作用域', note: '作用域越具体优先级越高；同名技能需要显式显示来源。' },
  { title: '依赖运行时', summary: '检查命令、包和运行时是否可用', note: '缺少依赖时说明缺项和恢复方式，不静默跳过执行。' },
  { title: '安全边界', summary: '权限、密钥与外部副作用', note: '技能正文不能授予权限；高影响动作仍由运行时策略控制。' },
  { title: '生命周期', summary: '发现、安装、启用、停用与归档', note: '状态变更保留来源与时间，删除前检查仍在使用的绑定。' },
  { title: '创作支持', summary: '模板、校验器与本地预览', note: '创作反馈应落到具体字段或文件位置，并提供修复方向。' },
  { title: '市场生态', summary: '来源、许可证和发布者信息', note: '第三方技能展示来源与审核状态，不将来源标记误作安全保证。' },
  { title: '可观测性', summary: '匹配、加载、执行和结果事件', note: '事件流携带运行 ID 与版本，敏感正文不进入普通日志。' },
  { title: '边界与不适用项', summary: '明确技能的排除条件', note: '写清什么时候不应该调用，降低误匹配和能力越界。' },
  { title: '成熟度评估', summary: '从草稿到稳定发布的检查维度', note: '成熟度用可验证证据衡量，包括测试、依赖声明和运行记录。' },
]
const activeScope = ref('all')
const query = ref('')
const selectedId = ref('brainstorming')
const activeTopic = ref(0)
const validationMode = ref('normal')
const selectedSkill = computed(() => skills.find(skill => skill.id === selectedId.value) || skills[0])
const filteredSkills = computed(() => skills.filter(skill => (activeScope.value === 'all' || skill.scope === activeScope.value) && `${skill.name} ${skill.id} ${skill.description}`.toLowerCase().includes(query.value.toLowerCase())))
const currentTopic = computed(() => topicDetails[activeTopic.value])
const issueCount = computed(() => validationMode.value === 'normal' ? 0 : validationMode.value === 'vague' ? 1 : 2)
watch(filteredSkills, rows => {
  if (rows.length && !rows.some(skill => skill.id === selectedId.value)) selectedId.value = rows[0].id
})

function setValidation(mode) { validationMode.value = mode }
function hasIssue(index) { return (validationMode.value === 'vague' && index === 2) || (validationMode.value === 'entry' && index === 1) }
</script>

<template>
  <section class="skills-registry" aria-label="Skill 能力单元">
    <header class="skills-header">
      <div class="skills-brand"><span><Sparkles :size="17" /></span><div><h1>Skill 能力单元</h1><small>Skill Registry · 包结构 / 发现 / 加载 / 执行形态 / 版本 / 安全</small></div></div>
      <div class="skills-metrics"><div><strong>9</strong><span>已安装</span></div><div><strong class="metric-green">6</strong><span>可用</span></div><div><strong class="metric-amber">1</strong><span>缺依赖</span></div><div><strong class="metric-red">1</strong><span>损坏</span></div><div><strong>9,300</strong><span>正文 tok</span></div></div>
      <div class="skills-tagline">Skill 解决「不知道该用哪套方法」</div>
    </header>
    <div class="skills-workbench">
      <aside class="skills-list-panel">
        <div class="scope-tabs"><button v-for="scope in scopes" :key="scope.id" :class="{ active: activeScope === scope.id }" @click="activeScope = scope.id">{{ scope.label }}<small>{{ scope.count }}</small></button></div>
        <label class="skills-search"><Search :size="14" /><input v-model="query" aria-label="搜索 Skill" placeholder="搜索名称或 ID" /><kbd>/</kbd></label>
        <div class="skills-list">
          <button v-for="skill in filteredSkills" :key="skill.id" class="skill-row" :class="{ selected: selectedId === skill.id }" @click="selectedId = skill.id">
            <i class="skill-led" :class="skill.state === '可用' ? 'ready' : skill.state === '缺依赖' ? 'warning' : 'broken'"></i><span class="skill-row-copy"><strong>{{ skill.name }} <small>v{{ skill.version }}</small></strong><code>{{ skill.id }}</code><span class="skill-row-meta">{{ skill.scopeLabel }} <em>{{ skill.source }}</em></span></span><span v-if="skill.state !== '可用'" class="skill-state" :class="skill.state === '缺依赖' ? 'warning' : 'broken'">{{ skill.state }}</span>
          </button>
          <div v-if="!filteredSkills.length" class="skills-empty">没有匹配的 Skill</div>
        </div>
        <footer class="skills-list-footer">共 {{ filteredSkills.length }} 个 · 启用 7 <span>作用域 {{ activeScope === 'all' ? '全部' : scopes.find(item => item.id === activeScope)?.label }}</span></footer>
      </aside>

      <section class="skills-spec-panel">
        <nav class="topic-tabs" aria-label="Skill 规范主题"><button v-for="(topic, index) in topics" :key="topic" :class="{ active: activeTopic === index }" @click="activeTopic = index"><small>{{ String(index + 1).padStart(2, '0') }}</small>{{ topic }}</button></nav>
        <div class="spec-scroll">
          <div class="spec-heading"><div><h2>{{ currentTopic.title }} <small>{{ selectedSkill.id }} · {{ activeTopic === 0 ? '6 条硬约束' : '规范与校验' }}</small></h2><p>{{ currentTopic.summary }}</p></div><div class="validation-actions"><button :class="{ chosen: validationMode === 'normal' }" @click="setValidation('normal')">恢复正常</button><button :class="{ chosen: validationMode === 'vague' }" @click="setValidation('vague')">缺陷：描述含糊</button><button :class="{ chosen: validationMode === 'entry' }" @click="setValidation('entry')">缺陷：入口缺失</button></div></div>
          <div class="spec-grid">
            <section class="manifest-section"><label><FileCode2 :size="13" /> {{ selectedSkill.id }}/SKILL.md · manifest</label><pre>{
  "name": "{{ selectedSkill.id }}",
  "description": "{{ selectedSkill.description }}",
  "version": "{{ selectedSkill.version }}",
  "license": "MIT",
  "tags": ["{{ selectedSkill.scope }}", "{{ selectedSkill.source }}"],
  "entry": "SKILL.md",
  "deps": { "bin": ["none"] }
}</pre><p class="spec-callout">{{ currentTopic.note }}</p><div class="manifest-foot"><span><Check :size="13" /> manifest 示例 · 本地演示数据</span><span>{{ selectedSkill.tokens }} tok</span></div></section>
            <aside class="checklist-section"><div class="checklist-title">清单校验 <strong :class="issueCount ? 'has-issues' : ''">{{ 6 - issueCount }} / 6 通过</strong></div><div v-for="(item, index) in ['元数据字段完整', 'entry 指向的文件存在', '描述写清「什么时候不用」', '正文长度在阈值内', '资源目录符合约定', '依赖声明可解析']" :key="item" class="check-row"><span :class="hasIssue(index) ? 'check-fail' : 'check-ok'">{{ hasIssue(index) ? '!' : '✓' }}</span><div><strong>{{ item }}</strong><small>{{ index === 0 ? 'name / description / version / license / tags / entry' : index === 1 && validationMode === 'entry' ? 'SKILL.md 未找到' : index === 2 && validationMode === 'vague' ? '缺少排除条件，模型无法判断何时不该调用' : index === 3 ? `${selectedSkill.tokens} tok / 上限 3,000` : index === 4 ? 'references/ assets/ scripts/ examples/' : '无外部依赖' }}</small></div></div></aside>
            <section class="tree-section"><h3>资源目录与入口约定</h3><pre>{{ selectedSkill.id }}/
├─ SKILL.md ← entry，正文指令
├─ references/ 按需读，不常驻
│  ├─ divergent.md
│  └─ converge.md
├─ assets/ 模板 · 样例
├─ scripts/ 可执行物
└─ examples/ 正例 / 反例</pre><p>入口只认 manifest 的 entry。允许嵌套目录，但查找顺序固定为 entry → SKILL.md → index.md。</p></section>
            <section class="naming-section"><h3>命名规范 <small>三者关系</small></h3><div class="naming-table"><div><b>维度</b><b>规则</b><b>示例</b></div><div><span>目录名 / ID</span><span>kebab-case，全局唯一</span><code>{{ selectedSkill.id }}</code></div><div><span>显示名</span><span>可本地化，不参与匹配</span><span>{{ selectedSkill.name }}</span></div><div><span>工具前缀</span><span>skill 声明的工具带前缀</span><code>{{ selectedSkill.id.replaceAll('-', '_') }}__run</code></div><div><span>版本标签</span><span>semver，不带 v 前缀</span><code>{{ selectedSkill.version }}</code></div></div><p class="naming-note"><AlertTriangle :size="13" /> ID 一旦发布就不能改：绑定关系、调用统计、审计日志全靠它。</p></section>
          </div>
          <footer class="coverage-footer"><span>本节覆盖 8 项 · 与清单逐条对应</span><span><Check :size="13" /> 元数据字段</span><span><Check :size="13" /> 正文指令</span><span><Check :size="13" /> 依赖声明</span><span><Check :size="13" /> 格式校验</span></footer>
        </div>
      </section>

      <aside class="skills-inspector">
        <header class="inspector-title"><strong>选择链路</strong><small>{{ selectedSkill.id }} v{{ selectedSkill.version }}</small></header>
        <div class="inspector-metrics"><div><strong>{{ selectedSkill.tokens === '—' ? '0' : selectedSkill.tokens.replace(',', '') }}</strong><span>常驻 tok</span></div><div><strong class="success-rate">97.2%</strong><span>成功率</span></div></div>
        <section class="inspector-section"><h3>一次选择的完整链路</h3><ol class="selection-flow"><li><span>① 用户输入</span><code>帮我处理 {{ selectedSkill.name }} 相关任务</code></li><li><span>② 候选集合</span><b class="flow-chip">2 个命中 · 语义 + 规则</b></li><li><span>③ 选中</span><b class="flow-chip selected-chip">{{ selectedSkill.id }}</b></li><li><span>④ 加载层</span><b class="flow-chip loaded-chip">元数据 + 正文</b></li><li><span>⑤ 执行形态</span><b class="flow-chip">提示词指令</b></li></ol></section>
        <section class="inspector-section context-section"><h3>上下文占用</h3><div v-for="(item, index) in [{label:'元数据', value:42, width:12}, {label:'正文', value:selectedSkill.tokens, width:48}, {label:'参考', value:'3,800', width:71}, {label:'脚本', value:'6,200', width:86}]" :key="item.label" class="token-meter"><span>{{ item.label }}</span><i><b :style="{ width: `${item.width}%` }" :class="`meter-${index}`"></b></i><code>{{ item.value }}</code></div><div class="injected-total"><span>当前实际注入</span><strong>{{ selectedSkill.tokens }} tok</strong></div></section>
        <section class="inspector-section binding-section"><h3>绑定位置 <small>2</small></h3><span class="binding-chip">{{ selectedSkill.scopeLabel }}</span><span class="binding-chip">proj:checkout</span></section>
        <section class="inspector-section event-section"><h3>事件流 <Activity :size="13" /></h3><div class="event-row"><i class="event-green"></i><span><b>{{ selectedSkill.id }} 被语义匹配选中 · score 0.91</b><small>14:22:07</small></span></div><div class="event-row"><i class="event-blue"></i><span><b>渐进式披露：仅注入 name + description</b><small>14:21:40</small></span></div><div class="event-row"><i class="event-amber"></i><span><b>k8s-deploy 缺依赖 kubectl，已跳过预检</b><small>14:18:12</small></span></div></section>
        <button class="help-link" @click="emit('help')"><CircleHelp :size="14" />关于 Skill 注册表<ChevronRight :size="13" /></button>
      </aside>
    </div>
    <div v-if="issueCount" class="skills-toast"><AlertTriangle :size="14" />已切换为缺陷演示状态</div>
  </section>
</template>

